import os,pathlib,json,stat
root=pathlib.Path('/home/appontrack/.ayo-private')
if root.is_symlink():raise RuntimeError('unsafe private directory')
root.mkdir(mode=0o700,exist_ok=True)
root.chmod(0o700)
p=root/'owner.json'
if p.exists():
 info=json.loads(p.read_text())
 if info.get('code_sha256')!='0aa9b9031769362b538bc721ce14b3039b0ef805feb347d0ee624c4431c9d317':raise RuntimeError('owner guard already provisioned differently; refusing overwrite')
else:
 fd=os.open(str(p),os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)
 with os.fdopen(fd,'w') as f:json.dump({'code_sha256':'0aa9b9031769362b538bc721ce14b3039b0ef805feb347d0ee624c4431c9d317'},f)
print(json.dumps({'guard':'ready','directory_outside_docroot':True,'owner_mode':oct(stat.S_IMODE(p.stat().st_mode))}))
